function applyTempColor(temp){
  const el = $('temperature'); if(!el) return;
  el.classList.remove('temp-freezing','temp-cold','temp-cool','temp-mild','temp-warm','temp-hot','temp-scorching');
  const v = Number(temp);
  if(v <= -15) el.classList.add('temp-freezing');
  else if(v <= -5) el.classList.add('temp-cold');
  else if(v <= 5) el.classList.add('temp-cool');
  else if(v <= 15) el.classList.add('temp-mild');
  else if(v <= 25) el.classList.add('temp-warm');
  else if(v <= 32) el.classList.add('temp-hot');
  else el.classList.add('temp-scorching');
}
function updateTempTrend(current, next){
  const wrap = $('tempTrendWrap');
  if(!wrap) return;
  if(next == null){ wrap.innerHTML=''; return; }
  const diff = Math.round(next - current);
  let cls, ic, label;
  if(diff > 0){ cls='up'; ic='i-arrow-up'; label=`+${diff}°`; }
  else if(diff < 0){ cls='down'; ic='i-arrow-down'; label=`${diff}°`; }
  else { cls='flat'; ic='i-minus'; label='0°'; }
  wrap.innerHTML = `<span class="temp-trend ${cls}">${svg(ic)}${label}</span>`;
}

function renderNowcast(forecast){
  if(!forecast || !forecast.list) return;
  const card = $('nowcastCard');
  const bars = $('nowcastBars');
  const sum = $('nowcastSummary');
  if(!card || !bars) return;
  const items = forecast.list.slice(0, 4);
  if(!items.length) return;
  card.style.display = 'block';
  bars.innerHTML = '';
  let maxPop = 0;
  items.forEach(it => {
    const pop = Math.round((it.pop || 0) * 100);
    maxPop = Math.max(maxPop, pop);
    const rain = it.rain ? (it.rain['3h'] || 0) : 0;
    const snow = it.snow ? (it.snow['3h'] || 0) : 0;
    const vol = rain + snow;
    const h = Math.max(6, pop);
    const cls = vol > 3 ? 'heavy' : pop > 40 ? 'filled' : '';
    const d = new Date(it.dt * 1000);
    bars.innerHTML += `<div class="nowcast-bar ${cls}" style="height:${h}%"><span class="nowcast-tip">${formatHour(d)} · ${pop}%</span></div>`;
  });
  const isRain = /rain|drizzle/i.test(forecast.list[0].weather[0].main);
  const willRain = items.some(it => (it.pop || 0) > 0.35);
  sum.innerHTML = maxPop > 60
    ? `${svg('i-alert-tri')} Высокая вероятность осадков — возьмите зонт`
    : willRain ? `${svg('i-droplet')} Возможны осадки (до ${maxPop}%)`
    : isRain ? `${svg('i-droplet')} Осадки продолжаются`
    : `${svg('i-check-circle')} Ближайшие 12 часов — без существенных осадков`;
}

function renderAQIForecast(data){
  const box = $('aqiForecast');
  const bars = $('aqiForecastBars');
  if(!box || !bars || !data.list) return;
  const byDay = {};
  data.list.forEach(it => {
    const d = new Date(it.dt * 1000);
    const k = d.toDateString();
    if(!byDay[k]) byDay[k] = [];
    byDay[k].push(it.main.aqi);
  });
  const days = Object.entries(byDay).slice(0, 5);
  if(!days.length) return;
  box.style.display = 'block';
  bars.innerHTML = '';
  days.forEach(([k, aqis]) => {
    const avg = Math.round(aqis.reduce((a,b)=>a+b,0) / aqis.length);
    const cls = avg <= 2 ? 'good' : avg === 3 ? 'moderate' : avg === 4 ? 'unhealthy' : 'hazardous';
    const d = new Date(k);
    const label = d.toLocaleDateString('ru-RU', { weekday: 'short' });
    bars.innerHTML += `<div class="aqi-forecast-bar"><div class="aqi-forecast-date">${label}</div><div class="aqi-forecast-pill ${cls}">${avg}</div></div>`;
  });
}

async function loadPollen(lat, lon){
  const block = $('pollenBlock');
  const content = $('pollenContent');
  if(!block || !content) return;
  try{
    const url = `https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${lat}&longitude=${lon}&current=alder_pollen,birch_pollen,grass_pollen,mugwort_pollen,olive_pollen,ragweed_pollen&timezone=auto`;
    const r = await fetch(url);
    if(!r.ok) throw 0;
    const d = await r.json();
    const c = d.current || {};
    const rows = [
      ['Ольха', c.alder_pollen],
      ['Берёза', c.birch_pollen],
      ['Злаки', c.grass_pollen],
      ['Полынь', c.mugwort_pollen],
      ['Олива', c.olive_pollen],
      ['Амброзия', c.ragweed_pollen]
    ].filter(([, v]) => v != null && !isNaN(v));
    if(!rows.length){ block.style.display = 'none'; return; }
    block.style.display = 'block';
    content.innerHTML = rows.map(([name, val]) => {
      const v = Math.max(0, Number(val));
      const pct = Math.min(100, v * 2);
      const level = v < 10 ? 'low' : v < 50 ? 'medium' : 'high';
      const lbl = v < 10 ? 'низк.' : v < 50 ? 'сред.' : 'выс.';
      return `<div class="pollen-row"><span class="pollen-name">${name}</span><div class="pollen-bar"><div class="pollen-fill ${level}" style="width:${pct}%"></div></div><span class="pollen-level">${lbl}</span></div>`;
    }).join('');
  }catch(e){ block.style.display = 'none'; }
}

async function loadYearAgo(lat, lon){
  const block = $('yearAgoBlock');
  const data = $('yearAgoData');
  if(!block || !data) return;
  try{
    const d = new Date();
    d.setFullYear(d.getFullYear() - 1);
    const date = d.toISOString().slice(0, 10);
    const url = `https://archive-api.open-meteo.com/v1/archive?latitude=${lat}&longitude=${lon}&start_date=${date}&end_date=${date}&daily=temperature_2m_max,temperature_2m_min,precipitation_sum&timezone=auto`;
    const r = await fetch(url);
    if(!r.ok) throw 0;
    const j = await r.json();
    const dd = j.daily;
    if(!dd || !dd.temperature_2m_max || dd.temperature_2m_max[0] == null){ block.classList.remove('show'); return; }
    const tU = settings.units === 'metric' ? '°C' : '°F';
    data.innerHTML = `
      <div>${svg('i-thermometer')} Макс: <strong>${Math.round(dd.temperature_2m_max[0])}${tU}</strong></div>
      <div>${svg('i-thermometer')} Мин: <strong>${Math.round(dd.temperature_2m_min[0])}${tU}</strong></div>
      <div>${svg('i-droplet')} Осадки: <strong>${(dd.precipitation_sum[0]||0).toFixed(1)} мм</strong></div>`;
    block.classList.add('show');
  }catch(e){ block.classList.remove('show'); }
}

// Мужская озвучка погоды: бесплатный Piper (Denis для RU) через TTS.ai.
// У сервиса есть бесплатная анонимная квота; ключ API не требуется.
const WP_TTS_API = 'https://api.tts.ai/v1';
let wpWeatherAudio = null;
let wpWeatherTtsBusy = false;
const WP_TTS_VOICE_CACHE_KEY = 'weatherProMaleTtsVoiceV1';

function wpTtsDelay(ms){ return new Promise(resolve => setTimeout(resolve, ms)); }

async function wpTtsFetchJson(url, options = {}, timeoutMs = 18000){
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try{
    const response = await fetch(url, { ...options, signal: controller.signal, cache: 'no-store' });
    const raw = await response.text();
    let data = {};
    try{ data = raw ? JSON.parse(raw) : {}; }catch(_){ data = { message: raw.slice(0, 240) }; }
    if(!response.ok){
      const message = data.detail || data.message || data.error || `HTTP ${response.status}`;
      throw new Error(String(message));
    }
    return data;
  }finally{ clearTimeout(timeout); }
}

async function wpGetMaleTtsVoice(languageCode){
  const cacheKey = `${WP_TTS_VOICE_CACHE_KEY}_${languageCode}`;
  try{
    const cached = JSON.parse(localStorage.getItem(cacheKey) || 'null');
    if(cached && cached.id && cached.model && Date.now() - cached.savedAt < 7 * 86400000) return cached;
  }catch(_){}

  const query = new URLSearchParams({ language: languageCode, gender: 'male' });
  const data = await wpTtsFetchJson(`${WP_TTS_API}/voices/?${query.toString()}`, {}, 12000);
  const voices = Array.isArray(data.voices) ? data.voices : [];
  const freeModels = new Set(['piper', 'vits', 'melotts', 'kokoro']);
  const suitable = voices.filter(v => String(v.gender || '').toLowerCase() === 'male'
    && freeModels.has(String(v.model || '').toLowerCase()));
  if(!suitable.length) throw new Error('Не найден бесплатный мужской голос для выбранного языка');

  // Denis — бесплатный мужской русский голос Piper; для английского берём доступный бесплатный мужской голос.
  const voice = suitable.find(v => languageCode === 'ru' && /denis/i.test(`${v.name || ''} ${v.id || ''}`))
    || suitable.find(v => /piper/i.test(String(v.model || '')))
    || suitable[0];
  if(!voice.id || !voice.model) throw new Error('Сервис не вернул идентификатор голоса');
  const selected = { id: voice.id, name: voice.name || voice.id, model: voice.model, language: languageCode, savedAt: Date.now() };
  try{ localStorage.setItem(cacheKey, JSON.stringify(selected)); }catch(_){}
  return selected;
}

async function wpGenerateMaleSpeech(text, languageCode){
  const voice = await wpGetMaleTtsVoice(languageCode);
  // Анонимный бесплатный тариф ограничивает одну генерацию 500 символами.
  const safeText = String(text || '').replace(/\s+/g, ' ').trim().slice(0, 480);
  if(!safeText) throw new Error('Нет текста для озвучивания');
  const job = await wpTtsFetchJson(`${WP_TTS_API}/tts/`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
    body: JSON.stringify({
      model: voice.model,
      voice: voice.id,
      text: safeText,
      language: languageCode,
      format: 'mp3',
      speed: 0.97
    })
  }, 25000);

  let audioUrl = job.result_url || job.audio_url || job.url || '';
  const jobId = job.uuid || job.job_id;
  if(!audioUrl && jobId){
    for(let attempt = 0; attempt < 24; attempt++){
      await wpTtsDelay(1250);
      const result = await wpTtsFetchJson(`${WP_TTS_API}/speech/results/?uuid=${encodeURIComponent(jobId)}`, {}, 12000);
      if(result.status === 'failed') throw new Error(result.error || 'Не удалось создать аудио');
      audioUrl = result.result_url || result.audio_url || result.url || '';
      if(audioUrl || result.status === 'completed') break;
    }
  }
  if(!audioUrl) throw new Error('Сервис не вернул аудиофайл');
  return { audioUrl, voiceName: voice.name };
}

function wpSpeakWithSystemMale(text, languageCode){
  if(!('speechSynthesis' in window) || typeof SpeechSynthesisUtterance === 'undefined')
    throw new Error('Озвучка не поддерживается этим браузером');
  window.speechSynthesis.cancel();
  const voices = window.speechSynthesis.getVoices();
  const langPrefix = languageCode === 'ru' ? 'ru' : 'en';
  const candidates = voices.filter(v => String(v.lang || '').toLowerCase().startsWith(langPrefix));
  const maleHints = /male|man|alex|andrew|daniel|david|dmitri|dmitry|denis|ivan|pavel|paul|sergey|sergei|yuri|nikita|русск.*муж|мужск/i;
  const chosen = candidates.find(v => maleHints.test(`${v.name || ''} ${v.voiceURI || ''}`)) || candidates[0] || null;
  const utterance = new SpeechSynthesisUtterance(text);
  utterance.lang = languageCode === 'ru' ? 'ru-RU' : 'en-US';
  if(chosen) utterance.voice = chosen;
  utterance.rate = 0.96;
  utterance.pitch = chosen && maleHints.test(`${chosen.name || ''} ${chosen.voiceURI || ''}`) ? 0.92 : 0.78;
  window.speechSynthesis.speak(utterance);
  return chosen ? chosen.name : 'системный голос с пониженным тоном';
}

async function speakWeather(){
  const city = $('locationName')?.textContent?.trim() || (lang === 'ru' ? 'вашем городе' : 'your city');
  const temp = $('temperature')?.textContent?.trim() || '';
  const desc = $('weatherDescription')?.textContent?.trim() || '';
  const hum = $('humidity')?.textContent?.trim() || '';
  const languageCode = lang === 'ru' ? 'ru' : 'en';
  const text = languageCode === 'ru'
    ? `Погода в городе ${city}. Температура ${temp}. ${desc}. Влажность ${hum}.`
    : `Weather in ${city}. Temperature ${temp}. ${desc}. Humidity ${hum}.`;

  if(wpWeatherTtsBusy){
    if(wpWeatherAudio){ try{ wpWeatherAudio.pause(); wpWeatherAudio.currentTime = 0; }catch(_){} }
    if('speechSynthesis' in window) window.speechSynthesis.cancel();
    showNotification(languageCode === 'ru' ? 'Озвучка остановлена' : 'Speech stopped');
    wpWeatherTtsBusy = false;
    return;
  }

  wpWeatherTtsBusy = true;
  if('speechSynthesis' in window) window.speechSynthesis.cancel();
  if(wpWeatherAudio){ try{ wpWeatherAudio.pause(); wpWeatherAudio.currentTime = 0; }catch(_){} }
  showNotification(languageCode === 'ru' ? 'Подключаем мужской голос…' : 'Loading male voice…');

  try{
    const generated = await wpGenerateMaleSpeech(text, languageCode);
    const audio = new Audio(generated.audioUrl);
    audio.preload = 'auto';
    // Немного понижаем тембр без сильного замедления речи (поддержка зависит от браузера).
    try{ audio.preservesPitch = false; audio.mozPreservesPitch = false; audio.webkitPreservesPitch = false; audio.playbackRate = 0.96; }catch(_){}
    wpWeatherAudio = audio;
    audio.onended = () => { wpWeatherTtsBusy = false; };
    audio.onerror = () => { wpWeatherTtsBusy = false; };
    await audio.play();
    showNotification(languageCode === 'ru'
      ? `Озвучка: мужской голос ${generated.voiceName}`
      : `Speech: male voice ${generated.voiceName}`);
  }catch(error){
    console.warn('Weather Pro male TTS unavailable; using device speech:', error);
    try{
      const fallbackName = wpSpeakWithSystemMale(text, languageCode);
      showNotification(languageCode === 'ru'
        ? `Облачный голос временно недоступен. Используется голос устройства: ${fallbackName}`
        : `Cloud voice unavailable. Using device voice: ${fallbackName}`, true);
    }catch(fallbackError){
      showNotification(languageCode === 'ru' ? 'Не удалось запустить озвучку' : 'Could not start speech', true);
    }
    wpWeatherTtsBusy = false;
  }
}
window.speakWeather=speakWeather;

function wp92Ui(ru,en){return lang==='en'?en:ru;}
function wp92RoundRect(ctx,x,y,w,h,r,fill,stroke){
  const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath();
  if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}
}
function wp92FitText(ctx,text,maxWidth,size,minSize=22,weight=600){
  let n=size;while(n>minSize){ctx.font=`${weight} ${n}px Inter, Arial, sans-serif`;if(ctx.measureText(String(text)).width<=maxWidth)break;n-=2;}return n;
}
function wp92Glow(ctx,x,y,r,color){const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,color);g.addColorStop(1,'rgba(5,12,28,0)');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2);}
function wp92ClipRoundRect(ctx,x,y,w,h,r){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath();ctx.clip();}
function wp92WeatherType(description=''){
  const d=String(description||'').toLocaleLowerCase();
  if(/гроза|грозов|thunder|lightning/.test(d))return 'thunder';
  if(/снег|snow|sleet|blizzard|метел/.test(d))return 'snow';
  if(/дожд|лив|rain|drizzle|shower/.test(d))return 'rain';
  if(/туман|fog|mist|haze/.test(d))return 'fog';
  if(/ясн|clear|sunny|солнеч/.test(d))return 'sun';
  if(/небольш.*облач|малооблач|перемен|partly|few clouds|scattered/.test(d))return 'partly';
  if(/облач|cloud|overcast/.test(d))return 'cloud';
  return 'partly';
}
function wp92WeatherGlyph(ctx,x,y,size,description=''){
  const type=wp92WeatherType(description),r=size;
  ctx.save();ctx.translate(x,y);ctx.lineCap='round';ctx.lineJoin='round';
  const drawSun=(sx,sy,s)=>{
    ctx.save();ctx.shadowColor='rgba(255,196,75,.4)';ctx.shadowBlur=s*.18;ctx.strokeStyle='#ffd36b';ctx.lineWidth=Math.max(3,s*.045);
    for(let a=0;a<Math.PI*2;a+=Math.PI/4){ctx.beginPath();ctx.moveTo(sx+Math.cos(a)*s*1.22,sy+Math.sin(a)*s*1.22);ctx.lineTo(sx+Math.cos(a)*s*1.55,sy+Math.sin(a)*s*1.55);ctx.stroke();}
    ctx.beginPath();ctx.arc(sx,sy,s,0,Math.PI*2);ctx.fillStyle='#ffc85b';ctx.fill();ctx.restore();
  };
  const drawCloud=()=>{
    ctx.save();ctx.shadowColor='rgba(73,159,255,.42)';ctx.shadowBlur=r*.2;ctx.beginPath();
    ctx.moveTo(-r*.72,r*.28);ctx.bezierCurveTo(-r*.95,r*.02,-r*.76,-r*.32,-r*.38,-r*.34);
    ctx.bezierCurveTo(-r*.23,-r*.83,r*.42,-r*.82,r*.53,-r*.32);
    ctx.bezierCurveTo(r*.95,-r*.35,r*1.04,r*.18,r*.78,r*.39);
    ctx.lineTo(-r*.68,r*.39);ctx.closePath();ctx.fillStyle='#e7f3ff';ctx.fill();ctx.restore();
  };
  if(type==='sun')drawSun(0,0,r*.53);
  else{
    if(type==='partly')drawSun(r*.33,-r*.34,r*.39);
    drawCloud();
    if(type==='rain'||type==='thunder'){
      ctx.save();ctx.shadowBlur=0;ctx.strokeStyle='#42c9ff';ctx.lineWidth=Math.max(4,r*.075);
      for(let i=0;i<3;i++){const xx=(i-1)*r*.42;ctx.beginPath();ctx.moveTo(xx,r*.48);ctx.lineTo(xx-r*.12,r*.78);ctx.stroke();}ctx.restore();
    }
    if(type==='snow'){
      ctx.save();ctx.shadowBlur=0;ctx.strokeStyle='#cce9ff';ctx.lineWidth=Math.max(3,r*.045);
      for(let i=0;i<3;i++){const xx=(i-1)*r*.48,yy=r*.64;ctx.beginPath();ctx.moveTo(xx-r*.11,yy);ctx.lineTo(xx+r*.11,yy);ctx.moveTo(xx,yy-r*.11);ctx.lineTo(xx,yy+r*.11);ctx.moveTo(xx-r*.08,yy-r*.08);ctx.lineTo(xx+r*.08,yy+r*.08);ctx.moveTo(xx-r*.08,yy+r*.08);ctx.lineTo(xx+r*.08,yy-r*.08);ctx.stroke();}ctx.restore();
    }
    if(type==='thunder'){
      ctx.save();ctx.shadowColor='rgba(255,208,82,.5)';ctx.shadowBlur=r*.2;ctx.beginPath();ctx.moveTo(r*.12,r*.36);ctx.lineTo(-r*.12,r*.77);ctx.lineTo(r*.08,r*.77);ctx.lineTo(-r*.02,r*1.12);ctx.lineTo(r*.34,r*.63);ctx.lineTo(r*.13,r*.63);ctx.closePath();ctx.fillStyle='#ffd15c';ctx.fill();ctx.restore();
    }
    if(type==='fog'){
      ctx.save();ctx.shadowBlur=0;ctx.strokeStyle='#9db7d5';ctx.lineWidth=Math.max(3,r*.055);[-.08,.18,.44].forEach((v,i)=>{ctx.beginPath();ctx.moveTo(-r*.62,r*(.48+v));ctx.lineTo(r*(i===1?.68:.5),r*(.48+v));ctx.stroke();});ctx.restore();
    }
  }
  ctx.restore();
}
function wp92WeatherData(){
  const el=id=>$(id)?.textContent?.trim()||'—';
  const w=lastWeatherData||{};
  return {city:el('locationName').split(',')[0]||w.name||currentCity||'—',temp:el('temperature'),desc:el('weatherDescription'),feels:el('feelsLike'),wind:el('windSpeed'),humidity:el('humidity'),pressure:el('pressure'),visibility:el('visibility'),unit:el('tempUnit')||'°C',date:new Date(),forecast:lastForecastData?.list||[],valid:!!(lastWeatherData||lastTemp!==null)};
}
function wp92ForecastItems(){
  const src=Array.isArray(lastForecastData?.list)?lastForecastData.list:[];if(!src.length)return [];
  const byDay=new Map();for(const item of src){if(!item?.dt||!item?.main)continue;const dt=new Date(item.dt*1000),key=`${dt.getFullYear()}-${dt.getMonth()}-${dt.getDate()}`;const hour=dt.getHours();const prev=byDay.get(key);if(!prev||Math.abs(hour-13)<Math.abs(new Date(prev.dt*1000).getHours()-13))byDay.set(key,item);}
  return Array.from(byDay.values()).slice(0,5);
}
function wp92DrawBase(ctx,w,h){
  const g=ctx.createLinearGradient(0,0,w,h);g.addColorStop(0,'#07101f');g.addColorStop(.48,'#101f3b');g.addColorStop(1,'#070d19');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
  wp92Glow(ctx,w*.82,h*.12,w*.62,'rgba(37,111,255,.34)');wp92Glow(ctx,w*.08,h*.83,w*.55,'rgba(0,205,255,.15)');
  ctx.save();ctx.globalAlpha=.12;ctx.strokeStyle='#8fc7ff';ctx.lineWidth=1;for(let y=40;y<h;y+=90){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}ctx.restore();
  wp92RoundRect(ctx,18,18,w-36,h-36,34,null,'rgba(145,190,255,.3)');
}
function wp92Metric(ctx,x,y,w,h,label,value,icon){
  wp92RoundRect(ctx,x,y,w,h,18,'rgba(14,29,53,.86)','rgba(139,184,255,.16)');
  ctx.textAlign='left';ctx.fillStyle='#87baff';ctx.font='600 20px Inter,Arial';ctx.fillText(icon,x+20,y+32);
  ctx.fillStyle='#8fa7c7';ctx.font='500 17px Inter,Arial';ctx.fillText(label,x+52,y+31);
  ctx.fillStyle='#f4f8ff';ctx.font='700 27px Inter,Arial';ctx.fillText(value,x+20,y+70);
}
async function wp92SaveCanvas(canvas,filename,successText){
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png',1));if(!blob){showNotification('Не удалось создать изображение',true);return;}
  const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);showNotification(successText);
}
function wp92DrawTemperature(ctx,x,y,temp,unit,maxWidth,size){
  const fontSize=wp92FitText(ctx,temp,maxWidth,size,66,300);ctx.textAlign='left';ctx.fillStyle='#fff';ctx.font=`300 ${fontSize}px Inter,Arial,sans-serif`;ctx.fillText(temp,x,y);
  const tempW=ctx.measureText(temp).width;const unitSize=Math.max(30,Math.min(54,fontSize*.34));ctx.font=`500 ${unitSize}px Inter,Arial,sans-serif`;ctx.fillStyle='#82b7ff';ctx.fillText(unit,x+tempW+12,y-unitSize*.28);
}
function wp92DrawForecastRow(ctx,items,{x,y,w,cardH=170,gap=12,large=false}={}){
  const n=Math.min(5,items.length),cw=(w-gap*Math.max(0,n-1))/Math.max(1,n);
  items.slice(0,5).forEach((f,i)=>{
    const xx=x+i*(cw+gap),date=new Date(f.dt*1000),day=i===0?wp92Ui('Сегодня','Today'):date.toLocaleDateString(lang==='ru'?'ru-RU':'en-US',{weekday:'short'});
    wp92RoundRect(ctx,xx,y,cw,cardH,18,'rgba(13,28,52,.92)','rgba(132,176,239,.25)');ctx.textAlign='center';ctx.fillStyle='#a9bfdc';ctx.font=`700 ${large?22:18}px Inter,Arial`;ctx.fillText(day,xx+cw/2,y+34);
    wp92WeatherGlyph(ctx,xx+cw/2,y+(large?96:76),large?44:36,f.weather?.[0]?.description||'');
    ctx.fillStyle='#f7faff';ctx.font=`800 ${large?32:27}px Inter,Arial`;ctx.fillText(`${Math.round(f.main.temp)}°`,xx+cw/2,y+(large?177:126));
    ctx.fillStyle='#8fa9ca';ctx.font=`600 ${large?16:14}px Inter,Arial`;ctx.fillText(`${Math.round(f.main.temp_max??f.main.temp)}° / ${Math.round(f.main.temp_min??f.main.temp)}°`,xx+cw/2,y+(large?222:cardH-12));
  });
}
function wp92DrawMetricTile(ctx,x,y,w,h,label,value,icon){
  wp92RoundRect(ctx,x,y,w,h,17,'rgba(14,29,53,.88)','rgba(139,184,255,.2)');
  ctx.textAlign='left';ctx.fillStyle='#83b8ff';ctx.font='700 20px Inter,Arial';ctx.fillText(icon,x+16,y+29);
  ctx.fillStyle='#91a9ca';ctx.font='600 15px Inter,Arial';ctx.fillText(label,x+43,y+28);
  ctx.fillStyle='#f4f8ff';ctx.font=`700 ${wp92FitText(ctx,value,w-28,25,15,700)}px Inter,Arial`;ctx.fillText(value,x+16,y+66);
}
