      ctx.strokeStyle=`rgba(224,241,255,${alpha*1.4})`;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(d.x+d.r*.2,d.y+d.r*.6);ctx.quadraticCurveTo(d.x+d.r*.55,d.y+d.r*1.8,d.x+d.r*.25,d.y+d.trail);ctx.stroke();
