    ctx.lineTo(midX,midY);ctx.lineTo(endX,endY);
    if(depth>0 && Math.random()>.3){ctx.save();ctx.beginPath();ctx.moveTo(midX,midY);lightningPath(midX,midY,dx*rand(.25,.52),dy*rand(.22,.42),depth-1);ctx.stroke();ctx.restore();}
