      flash.addColorStop(0,`rgba(222,236,255,${.28*fade})`);flash.addColorStop(.42,`rgba(167,198,235,${.13*fade})`);flash.addColorStop(1,'rgba(130,165,210,0)');ctx.fillStyle=flash;ctx.fillRect(0,0,state.width,state.height);
