function applyWeatherAtmosphere(data){
  if(!data || !data.weather || !data.weather[0]) return;
  const w=data.weather[0], main=String(w.main||'').toLowerCase(), desc=String(w.description||'').toLowerCase();
  const id=Number(w.id||0);
  const type=(id>=200&&id<300)||/thunder|lightning|гроза/.test(main+' '+desc)?'thunder'
    :((id>=600&&id<700)||/snow|снег|sleet|метел/.test(main+' '+desc))?'snow'
    :((id>=300&&id<600)||/rain|drizzle|дожд|лив|морос/.test(main+' '+desc))?'rain'
    :(/mist|fog|haze|smoke|dust|туман|дымка|мгла/.test(main+' '+desc)||[701,711,721,731,741,751,761,762].includes(id))?'fog'
    :(/clear|sun|ясно/.test(main+' '+desc)||id===800)?'clear'
    :'clouds';
  document.body.classList.remove('wp-clear','wp-clouds','wp-rain','wp-snow','wp-thunder','wp-fog');
  document.body.classList.add('wp-'+type);
  if(window.WPWeatherScene && typeof window.WPWeatherScene.update==='function') window.WPWeatherScene.update(data,type);
}
function renderWeatherIntelligence(current,forecast){
  if(!current || !current.main) return;
  const set=(id,value)=>{const el=$(id);if(el)el.textContent=value;};
  const metric=(settings.units||'metric')==='metric';
  const tempUnit=metric?'°C':'°F';
  const windUnit=metric?'м/с':'миль/ч';
  const next=(forecast&&forecast.list?forecast.list:[]).slice(0,8);
  const rainMax=next.length?Math.round(Math.max(...next.map(x=>(x.pop||0)*100))):0;
  set('wpFeels',Math.round(current.main.feels_like)+tempUnit);
  set('wpRain',rainMax+'%');
  set('wpWind',Math.round((current.wind?.speed||0)*10)/10+' '+windUnit);
  set('wpHumidity',(current.main.humidity??'—')+'%');
  const summary=$('wpBriefSummary'),tip=$('wpBriefTip');
  const desc=current.weather?.[0]?.description||'Погодные условия обновлены';
  const t=Math.round(current.main.temp);
  let headline=`Сейчас ${desc}. Температура ${t>0?'+':''}${t}${tempUnit}.`;
  let advice='Ориентируйтесь на ощущаемую температуру и выбирайте одежду по погоде.';
  if(rainMax>=55){headline+=' В ближайшие часы вероятны осадки.';advice='Возьмите зонт или непромокаемую верхнюю одежду.';}
  else if((current.wind?.speed||0)>(metric?12:26.8)){headline+=' Ожидается сильный ветер.';advice='Лучше выбрать одежду, защищающую от ветра, и быть осторожнее на открытых участках.';}
  else if(t<=0){advice='На улице холодно: пригодятся тёплая куртка, закрытая обувь и перчатки.';}
  else if(t>=27){advice='Тепло или жарко: пейте достаточно воды и не забывайте о защите от солнца.';}
  else if(/snow|снег/i.test(desc)){advice='Возможна скользкая поверхность — выбирайте обувь с хорошим сцеплением.';}
  if(summary) summary.textContent=headline;
  if(tip) tip.innerHTML=`${svg('i-sparkles')}<span>${esc(advice)}</span>`;
  const grid=$('wpHourGrid');
  if(grid){
    grid.innerHTML='';
    if(!next.length){grid.innerHTML='<div class="wp-intel-empty">Почасовой прогноз пока недоступен.</div>';}
    next.forEach(item=>{
      const date=new Date(item.dt*1000);
      const hour=date.toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
      const rain=Math.round((item.pop||0)*100);
      const icon=iconFor(item.weather?.[0]?.main||'Clouds');
      const el=document.createElement('div');el.className='wp-hour';
      el.innerHTML=`<div class="wp-hour-time">${hour}</div><div class="wp-hour-icon">${svg(icon)}</div><div class="wp-hour-temp">${Math.round(item.main.temp)}°</div><div class="wp-hour-rain">${rain?rain+'% '+wp5FaIcon('fa-umbrella'):'—'}</div>`;
      grid.appendChild(el);
    });
  }
}


